#! /bin/bash

# GENERIC ROS2 LAUNCHER FOR gazebo-classic-airsim-sitl.
# ALWAYS STARTS THE uXRCE-DDS AGENT AND THE AIRSIM ROS2 BRIDGE, THEN RUNS THE APP
# SELECTED BY ${ROS2_APP} (scripts/ros2/apps/<ROS2_APP>.sh). DO NOT EDIT THIS FILE
# TO ADD APPS - JUST DROP A NEW scripts/ros2/apps/<name>.sh AND SET ROS2_APP=<name>
# IN envs/ros2.env. (The default A4VAI stack lives in apps/a4vai.sh.)

# INITIAL STATEMENTS
# >>>----------------------------------------------------

# SET THE BASIC ENVIRONMENT VARIABLE
export TERM=xterm-256color

# SET THE BASE DIRECTORY
BASE_DIR=$(dirname $(readlink -f "$0"))
WORKSPACE_DIR=$(dirname $(dirname $(readlink -f "$0")))

# SOURCE THE ENVIRONMENT AND FUNCTION DEFINITIONS
for file in ${BASE_DIR}/include/*.sh; do
    source ${file}
done
# <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<


# MAIN STATEMENTS
# >>>----------------------------------------------------

source ${BASE_DIR}/sourceAll.sh

CheckFileExists ${BASE_DIR}/uxrce-dds.sh
CheckFileExecutable ${BASE_DIR}/uxrce-dds.sh

CheckFileExists ${BASE_DIR}/airsim-bridge.sh
CheckFileExecutable ${BASE_DIR}/airsim-bridge.sh

# CREATE DIRECTORY FOR LOGS
CheckDirExists ${WORKSPACE_DIR}/logs create
rm -rf ${WORKSPACE_DIR}/logs/*

# ALWAYS RUN THE uXRCE-DDS AGENT (PX4 uORB <-> ROS2 DDS) AND THE AIRSIM ROS2 BRIDGE
touch ${WORKSPACE_DIR}/logs/uxrce-dds.log
${BASE_DIR}/uxrce-dds.sh 2>&1 | tee ${WORKSPACE_DIR}/logs/uxrce-dds.log &
touch ${WORKSPACE_DIR}/logs/airsim-bridge.log
if [ "${PILS_LINK:-lan}" = wan ]; then
    # PILS over a routed link (onboard computer on Tailscale / 5G): the AirSim bridge runs next to Unreal on the
    # simulator PC (scripts/dev/ctrack_super.sh) and its lidar / odometry topics arrive over one TCP connection
    python3 ${BASE_DIR}/tools/topic_relay.py recv ${PILS_RELAY_PORT:-9750} 2>&1 | tee ${WORKSPACE_DIR}/logs/airsim-bridge.log &
else
    ${BASE_DIR}/airsim-bridge.sh 2>&1 | tee ${WORKSPACE_DIR}/logs/airsim-bridge.log &
fi

# ALSO RUN FOXGLOVE BRIDGE (Foxglove Studio connects at ws://<host>:8765).
# foxglove_bridge is baked into the ROS2 image (docker/ros2-env.Dockerfile).
touch ${WORKSPACE_DIR}/logs/foxglove_bridge.log
ros2 launch foxglove_bridge foxglove_bridge_launch.xml port:=8765 2>&1 | tee ${WORKSPACE_DIR}/logs/foxglove_bridge.log &

# STATIC TF world(ENU, PX4 원점=스폰) -> airsim_world(AirSim 맵 원점).
# 가시화 정렬용: 원시 AirSim 토픽(TF 루트 airsim_world)이 Foxglove 에서 어댑터의
# world 프레임과 겹쳐 보이게 한다. 회전 없음: AirSim ROS2 래퍼가 내부 NED 를 (x,-y,-z)로
# 바꿔 내보내고 GazeboDrone 이 Gazebo ENU 를 같은 규약으로 넣으므로 airsim_world 축 =
# Gazebo world ENU 축 (어댑터 보정 로그의 yaw diff ~0 deg 로 확인).
# 병진 = -스폰위치(ENU): GAZEBO_POSE (scripts/include/commonEnv.sh) 를 바꾸면 같이 수정.
# (PX4 EKF 고도 바이어스는 런마다 달라 z 는 0 으로 둔다.)
ros2 run tf2_ros static_transform_publisher \
    --x 27.5 --y -27.5 --z 0 \
    --qx 0 --qy 0 --qz 0 --qw 1 \
    --frame-id world --child-frame-id airsim_world \
    > /dev/null 2>&1 &

# STAGE 1: WAIT UNTIL THE uXRCE-DDS AGENT HAS BRIDGED PX4 (/fmu TOPICS PRESENT).
EchoYellow "[$(basename "$0")] WAITING FOR uXRCE-DDS AGENT + PX4 (/fmu TOPICS)..."
agent_ready=0
for _i in $(seq 1 60); do
    if ros2 topic list 2>/dev/null | grep -q "^/fmu/"; then
        agent_ready=1
        break
    fi
    sleep 1
done
if [ "${agent_ready}" -eq 1 ]; then
    EchoGreen "[$(basename "$0")] /fmu TOPICS AVAILABLE - PX4 BRIDGED."
else
    EchoRed "[$(basename "$0")] TIMEOUT WAITING FOR /fmu TOPICS."
fi

# STAGE 2: WAIT UNTIL PX4 IS READY FOR TAKEOFF (pre-arm checks pass), so the app does
# NOT command arm/offboard before EKF/GPS have converged ("Ready for takeoff").
EchoYellow "[$(basename "$0")] WAITING FOR PX4 TO BE READY FOR TAKEOFF..."
px4_ready=0
for _i in $(seq 1 120); do
    if timeout 3 ros2 topic echo --once /fmu/out/vehicle_status_v1 2>/dev/null | grep -q "pre_flight_checks_pass: true"; then
        px4_ready=1
        break
    fi
    sleep 1
done
if [ "${px4_ready}" -eq 1 ]; then
    EchoGreen "[$(basename "$0")] PX4 READY FOR TAKEOFF - STARTING APP."
else
    EchoRed "[$(basename "$0")] TIMEOUT WAITING FOR PX4 READY - STARTING APP ANYWAY."
fi

# RUN THE SELECTED ROS2 APP (DROP-IN: scripts/ros2/apps/<ROS2_APP>.sh)
export WORKSPACE_DIR BASE_DIR
APP_SCRIPT=${BASE_DIR}/apps/${ROS2_APP}.sh
if [ -n "${ROS2_APP}" ] && [ -x "${APP_SCRIPT}" ]; then
    EchoGreen "[$(basename "$0")] RUNNING ROS2 APP: ${ROS2_APP}"
    touch ${WORKSPACE_DIR}/logs/${ROS2_APP}.log
    ${APP_SCRIPT} 2>&1 | tee ${WORKSPACE_DIR}/logs/${ROS2_APP}.log &
elif [ -n "${ROS2_APP}" ]; then
    EchoRed "[$(basename "$0")] ROS2_APP='${ROS2_APP}' BUT ${APP_SCRIPT} NOT FOUND/EXECUTABLE. IDLING."
else
    EchoYellow "[$(basename "$0")] ROS2_APP IS EMPTY. RUNNING AGENT + AIRSIM BRIDGE ONLY (IDLE)."
    EchoYellow "[$(basename "$0")] SET ROS2_APP=<name> IN envs/ros2.env AND ADD scripts/ros2/apps/<name>.sh"
fi

sleep infinity

# <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
